import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.TQKaXlFR.js";const u=JSON.parse('{"title":"贡献代码与问题报告","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/contribution.md","filePath":"contributing/contribution.md"}'),r={name:"contributing/contribution.md"};function l(n,e,s,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="贡献代码与问题报告" tabindex="-1">贡献代码与问题报告 <a class="header-anchor" href="#贡献代码与问题报告" aria-label="Permalink to &quot;贡献代码与问题报告&quot;">​</a></h1><p>本页面向准备修复问题或扩展现有模块的开发者。先确定自己使用的<a href="./../releases/versions.html">版本组合</a>、仓库地址与权限范围，再选择一个可验证的小变更；不要根据依赖名称宣称尚未交付的能力。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>有效问题报告应包含：请求方法/路径或页面、预期与实际结果、提交/产物版本、工具链、脱敏配置键、最小复现步骤、HTTP与业务code。列出已尝试的恢复，区分环境、权限、供应商与代码缺陷。</p><p>不要公开真实手机号、密码、JWT、配置密钥、AI prompt/context、用户导入文件、数据库dump、QA日志或临时账号。敏感安全问题使用维护者实际提供的私有渠道；未配置反馈URL时不杜撰邮箱/issue地址，也不把上游Vbenissue当成本项目支持入口。</p><h2 id="实现步骤" tabindex="-1">实现步骤 <a class="header-anchor" href="#实现步骤" aria-label="Permalink to &quot;实现步骤&quot;">​</a></h2><ol><li>从确定基线建立feature/fix分支，记录两端SHA与自己负责文件。</li><li>读真实页面→API→Controller→服务→DTO/权限/迁移，确定正常和失败行为。</li><li>保持最小修改；数据结构变更通过新迁移，不编辑已成功执行的历史SQL。</li><li>给行为变化加有意义的验证，覆盖真实失效、权限/资源范围、并发版本和空态，不照抄实现写假测试。</li><li>更新对应单一正文页的字段/例子/源码位置，避免旧后端docs另写第二份同内容指南。</li><li>运行适用门槛并记录失败证据，最后提交可审阅diff和准确交付SHA。</li></ol><p>扩展步骤见<a href="./../development/module-extension.html">模块扩展</a>；轻量AI/低代码接缝不能演变成未经授权的新SDK、权限管理器或匿名填写功能。</p><h2 id="review交付" tabindex="-1">Review交付 <a class="header-anchor" href="#review交付" aria-label="Permalink to &quot;Review交付&quot;">​</a></h2><p>提供变更目的、影响的身份/请求/字段、兼容性与迁移说明、实际测试命令及退出码、产物对应SHA、未验证项。前后端只改一端时明确另一端兼容基线；新增provider需要单独授权验证，不能在PR测试中发送真实短信/模型请求。</p><p>每个必需用例实际执行，缺失/跳过不能写PASS。Controller语义变化更新接口目录和错误页；组件参数变化更新组件参考。文档-only变更不需要为了凑证据重跑所有业务，但必须检查内容、链接、锚点和示例，完整站点组合后构建。</p><h2 id="许可与公开边界" tabindex="-1">许可与公开边界 <a class="header-anchor" href="#许可与公开边界" aria-label="Permalink to &quot;许可与公开边界&quot;">​</a></h2><p>保留项目及依赖的上游归属，复制第三方代码先核对许可和来源，不直接搬运开源文档正文。公开仓库存在或有写权限不等于可以推送包含个人历史、私有配置的代码；历史审计与正式发布另走项目流程。</p><p>贡献完成的判断是代码/文档可审阅、真实验证结论明确、负责人能按最终SHA继续集成；不是把任务记录改成“完成”。遇到无法验证的依赖写明具体缺项和恢复条件。</p><h2 id="源码依据与下一步" tabindex="-1">源码依据与下一步 <a class="header-anchor" href="#源码依据与下一步" aria-label="Permalink to &quot;源码依据与下一步&quot;">​</a></h2><p>规范依据是现有Controller/服务/DTO/测试、两端<code>.github/workflows/ci.yml</code>、后端<code>scripts/quality/required-tests.txt</code>、前端<code>scripts/verify-app-tests.mjs</code>与<code>scripts/check-needs.mjs</code>。详细命令见<a href="./../operations/quality-gates.html">质量门槛</a>，文档更新见<a href="./documentation.html">文档贡献</a>。</p>',16)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
